#include "care_arrangement_retention.hpp"
#include "resident/domains/actor_foundation/condition_source_read.hpp"
namespace hanmo::resident {namespace {
bool same(const SourceRef& a,const SourceRef& b){return a.domain==b.domain&&a.kind==b.kind&&a.id==b.id;}
bool same(const SourcePin& a,const SourcePin& b){return a.consumer.domain==b.consumer.domain&&a.consumer.kind==b.consumer.kind&&a.consumer.id==b.consumer.id&&a.consumer.slot==b.consumer.slot&&same(a.source,b.source)&&a.reason==b.reason;}
}
RequiredSourceConsumerSlot care_acceptance_consumer_slot(CareAcceptancePinSlot slot){switch(slot){case CareAcceptancePinSlot::requirement_transition:return {"care_requirements","accepted_caregiver","requirement_transition_ref"};case CareAcceptancePinSlot::institutional_assignment:return {"care_requirements","accepted_caregiver","institutional_assignment_ref"};case CareAcceptancePinSlot::allowed_dependency:return {"care_requirements","accepted_caregiver","allowed_dependency_refs"};case CareAcceptancePinSlot::provision:return {"care_requirements","accepted_caregiver","provision_arrangement_refs"};case CareAcceptancePinSlot::fee_arrangement:return {"care_requirements","accepted_caregiver","fee_arrangement_refs"};case CareAcceptancePinSlot::guardianship_permission:return {"care_requirements","accepted_caregiver","guardianship_permission_refs"};case CareAcceptancePinSlot::acceptance_condition_seed:return {"care_requirements","accepted_caregiver","acceptance_condition_seed"};case CareAcceptancePinSlot::acceptance_condition_receipt:return {"care_requirements","accepted_caregiver","acceptance_condition_receipt"};}return {};}
Status visit_care_acceptance_source_pins(const CareAcceptanceContext& x,CareAcceptancePinSlot slot,CareAcceptancePinSink& sink){auto valid=validate_accepted_caregiver_sources(x);if(!valid.ok)return valid;const auto spec=care_acceptance_consumer_slot(slot);if(spec.domain.empty())return common_failure("UnknownCareAcceptancePinSlot",{},ErrorKind::unsupported_capability);for(const auto& row:x.accepted.rows()){auto emit=[&](const SourceRef& source){return sink.actual_pin({{spec.domain,spec.kind,row.first,spec.slot},source,SourcePinReason::dependent_state});};if(slot==CareAcceptancePinSlot::acceptance_condition_seed||slot==CareAcceptancePinSlot::acceptance_condition_receipt){const auto& head=row.second.acceptance_condition_head;if(slot==CareAcceptancePinSlot::acceptance_condition_receipt&&!head.latest_receipt_ref)continue;valid=emit(slot==CareAcceptancePinSlot::acceptance_condition_seed?initial_condition_seed_source(head.initial_condition_seed_ref):character_condition_receipt_source(*head.latest_receipt_ref));if(!valid.ok)return valid;continue;}if(slot==CareAcceptancePinSlot::requirement_transition){valid=emit(row.second.requirement_transition_ref);if(!valid.ok)return valid;continue;}if(slot==CareAcceptancePinSlot::institutional_assignment){if(row.second.provider.institutional_assignment_ref){valid=emit(row.second.provider.institutional_assignment_ref->source_ref);if(!valid.ok)return valid;}continue;}const std::vector<MomentOwnerSource>* refs=nullptr;switch(slot){case CareAcceptancePinSlot::allowed_dependency:refs=&row.second.terms.allowed_dependency_refs;break;case CareAcceptancePinSlot::provision:refs=&row.second.terms.provision_arrangement_refs;break;case CareAcceptancePinSlot::fee_arrangement:refs=&row.second.terms.fee_arrangement_refs;break;case CareAcceptancePinSlot::guardianship_permission:refs=&row.second.terms.guardianship_permission_refs;break;default:break;}if(!refs)return common_failure("UnknownCareAcceptancePinSlot",{},ErrorKind::internal);for(const auto& ref:*refs){valid=emit(ref.source_ref);if(!valid.ok)return valid;}}return common_success();}
Status validate_care_acceptance_source_pin(const CareAcceptanceContext& x,CareAcceptancePinSlot slot,const SourcePin& pin){struct Find final:CareAcceptancePinSink{const SourcePin& wanted;std::size_t count=0;explicit Find(const SourcePin& p):wanted(p){}Status actual_pin(const SourcePin& p)override{if(same(wanted,p))++count;return common_success();}}find(pin);auto s=visit_care_acceptance_source_pins(x,slot,find);if(!s.ok)return s;return find.count==1?common_success():common_failure("CareAcceptancePinNotActual",pin.consumer.id,ErrorKind::internal);}
}
